argv:
$paths = @('docs\ADAPTIVE_V5_PLUS_VA_CACH_DOC_EVIDENCE.md','README.md','docs\COMPLETION_REPORT.md','docs\FAILURES.md','results\adaptive_acceptance\2026-10-15-v5-plus\REPORT.md')
$blockCount = 0
$tableCount = 0
foreach ($file in $paths) {
    $content = Get-Content -Raw -Encoding UTF8 -LiteralPath $file
    foreach ($block in [regex]::Matches($content, '(?ms)^```powershell\s*\r?\n(.*?)^```')) {
        $scanTokens = $null; $scanErrors = $null
        $null = [System.Management.Automation.Language.Parser]::ParseInput($block.Groups[1].Value, [ref]$scanTokens, [ref]$scanErrors)
        if ($scanErrors.Count -gt 0) { throw ($file + ': PowerShell syntax error') }
        $blockCount++
    }
    $width = 0
    foreach ($line in ($content -split '\r?\n')) {
        if ($line.StartsWith('|')) {
            $current = ([regex]::Matches($line, '\|')).Count
            if ($width -eq 0) { $width = $current; $tableCount++ }
            elseif ($current -ne $width) { throw ($file + ': inconsistent Markdown table width') }
        } else { $width = 0 }
    }
}
[PSCustomObject]@{status='PASS';markdown_files=$paths.Count;powershell_blocks=$blockCount;tables=$tableCount} | ConvertTo-Json

